        InputStream stream = new ByteArrayInputStream(data) {
            @Override
            public synchronized int read(byte[] target, int offset, int length) {
                return super.read(target, offset, Math.min(length, 2));
            }
        };
        byte[] buffer = new byte[data.length];
        stream.read(buffer);
        System.out.println(HexFormat.of().formatHex(buffer));
    }
}

import json
import sys


def append_item(value, items=None):
    if items is None:
        items = []
    items.append(value)
    return items


if __name__ == "__main__":
    append_item(int(sys.argv[1]))
    print(json.dumps(append_item(int(sys.argv[2])), separators=(",", ":")))

